        statisticId: createStatisticId([
          source.participantId,
          'season',
          row.competitionId ?? '',
          season,
        ]),
        scope: 'season',
        statisticCode: 'participant_season',
        competitionId: row.competitionId,
        competitionName: row.competitionName,
        seasonId,
        season,
      });
      continue;
    }

    if (scope === 'competition') {
