// competition alone, and Â§7 needs extending to record it.
//
// Every level excludes super-over innings, per Â§7 and issue #104, and groups by
// person identifier rather than display name: Â§10 records that names are not
// identity.
// ---------------------------------------------------------------------------

export const participantAggregateBattingSchema = z.object({
  runsScored: z.number().int().nonnegative(),
  ballsFaced: z.number().int().nonnegative(),
  fours: z.number().int().nonnegative(),
  sixes: z.number().int().nonnegative(),
  strikeRate: z.number().nonnegative().nullable(),
});

export const participantAggregateBowlingSchema = z.object({
  runsConceded: z.number().int().nonnegative(),
  // Wides and no-balls are charged to the bowler, including byes and leg-byes
  // run off a wide (Law 22.6). Other extras are deliberately not presented as a
  // bowler figure.
  wides: z.number().int().nonnegative(),
  noBalls: z.number().int().nonnegative(),
  legalBallsBowled: z.number().int().nonnegative(),
  wicketsTaken: z.number().int().nonnegative(),
  // Legal balls are counted from delivery rows. Overs and economy rate need a
  // balls-per-over divisor, which is a fixture-level fact: Â§10 forbids assuming
  // six. Where a group spans fixtures with different values there is no single
  // correct divisor, so both are null and MIXED_BALLS_PER_OVER is warned.
  ballsPerOver: z.number().int().positive().nullable(),
  oversBowled: z
    .string()
    .regex(/^\d+\.\d+$/)
    .nullable(),
  economyRate: z.number().nonnegative().nullable(),
});

const participantAggregateCommonSchema = z.object({
  statisticId: apiIdentifierSchema,
  participantId: apiIdentifierSchema,
  participantName: z.string().min(1),
  // Fixtures the participant actually appeared in as striker or bowler. This is
  // deliberately narrower than the fixture history at
  // /participants/{id}/fixtures, where participation is squad selection and a
  // player selected but not called upon still played.
  fixtureCount: z.number().int().nonnegative(),
  sourceEventCount: z.number().int().nonnegative(),
  // Null where the participant appears in no accepted delivery in this group as
  // a striker, or as a bowler, respectively. A zero is a real figure and is not
  // used to stand in for an absent one.
  batting: participantAggregateBattingSchema.nullable(),
  bowling: participantAggregateBowlingSchema.nullable(),
});

export const participantSeasonAggregateSchema = participantAggregateCommonSchema.extend({
  scope: z.literal('season'),
  statisticCode: z.literal('participant_season'),
  // Null for a fixture recorded without a competition. Season is stored as text
  // on the fixture and takes forms such as 2016/17, so it is never an integer.
  competitionId: apiIdentifierSchema.nullable(),
  competitionName: z.string().min(1).nullable(),
  seasonId: apiIdentifierSchema.nullable(),
  season: z.string().min(1),
});

export const participantCompetitionAggregateSchema = participantAggregateCommonSchema.extend({
  scope: z.literal('competition'),
  statisticCode: z.literal('participant_competition'),
  competitionId: apiIdentifierSchema.nullable(),
  competitionName: z.string().min(1).nullable(),
});

export const participantCareerAggregateSchema = participantAggregateCommonSchema.extend({
  scope: z.literal('career'),
  statisticCode: z.literal('participant_career'),
});

export const participantAggregateSchema = z.discriminatedUnion('scope', [
  participantSeasonAggregateSchema,
  participantCompetitionAggregateSchema,
  participantCareerAggregateSchema,
]);

export const participantAggregatesWarningSchema = z.object({
  code: z.enum(['NO_ACCEPTED_EVENTS', 'COMPETITION_UNKNOWN', 'MIXED_BALLS_PER_OVER']),
  message: z.string().min(1),
  competitionId: apiIdentifierSchema.optional(),
  season: z.string().min(1).optional(),
});

export const participantAggregatesSchema = z.object({
  participantId: apiIdentifierSchema,
  participantName: z.string().min(1),
  status: z.enum(['complete', 'partial']),
  scope: z.object({
    superOversIncluded: z.literal(false),
  }),
  warnings: z.array(participantAggregatesWarningSchema),
  statistics: z.array(participantAggregateSchema),
});

export const participantAggregateScopeSchema = z.enum(['season', 'competition', 'career']);

export const participantAggregatesQuerySchema = z.object({
  scope: participantAggregateScopeSchema.optional(),
});

export const participantAggregatesResponseSchema = createResourceResponseSchema(
  participantAggregatesSchema,
);

import { describe, expect, test } from 'vitest';

import { deriveParticipantAggregates } from '../../src/modules/statistics/participant-aggregates.derivation';
import type {
  ParticipantAggregateRow,
  ParticipantAggregatesSource,
} from '../../src/modules/statistics/participant-aggregates.model';

function row(overrides: Partial<ParticipantAggregateRow> = {}): ParticipantAggregateRow {
  return {
    competitionGrouped: true,
    seasonGrouped: true,
    competitionId: '10',
    competitionName: 'Test League',
    season: '2016/17',
    fixtureCount: 1,
    sourceEventCount: 0,
    battingDeliveryCount: 0,
    runsScored: 0,
    ballsFaced: 0,
    fours: 0,
    sixes: 0,
    bowlingDeliveryCount: 0,
    runsConceded: 0,
    wides: 0,
    noBalls: 0,
    legalBallsBowled: 0,
    wicketsTaken: 0,
    ballsPerOver: 6,
    ...overrides,
  };
}

function source(rows: ParticipantAggregateRow[]): ParticipantAggregatesSource {
  return {
    participantId: '101',
    participantName: 'BB McCullum',
    rows,
  };
}

const seasonRow = row({
  competitionGrouped: true,
  seasonGrouped: true,
  sourceEventCount: 60,
  battingDeliveryCount: 60,
  runsScored: 116,
  ballsFaced: 56,
  fours: 12,
  sixes: 8,
});

const competitionRow = row({
  competitionGrouped: true,
  seasonGrouped: false,
  season: null,
  fixtureCount: 2,
  sourceEventCount: 90,
  battingDeliveryCount: 90,
  runsScored: 150,
  ballsFaced: 80,
  fours: 15,
  sixes: 9,
});

const careerRow = row({
  competitionGrouped: false,
  seasonGrouped: false,
  competitionId: null,
  competitionName: null,
  season: null,
  fixtureCount: 3,
  sourceEventCount: 120,
  battingDeliveryCount: 120,
  runsScored: 200,
  ballsFaced: 110,
  fours: 20,
  sixes: 11,
});

describe('participant aggregate derivation', () => {
  test('names each grouping set as a season, competition or career level', () => {
    const result = deriveParticipantAggregates(source([seasonRow, competitionRow, careerRow]), {});

    expect(result.status).toBe('complete');
    expect(result.scope).toEqual({ superOversIncluded: false });
    expect(
      result.statistics.map((statistic) => ({
        scope: statistic.scope,
        statisticCode: statistic.statisticCode,
      })),
    ).toEqual([
      { scope: 'season', statisticCode: 'participant_season' },
      { scope: 'competition', statisticCode: 'participant_competition' },
      { scope: 'career', statisticCode: 'participant_career' },
    ]);
  });

  test('recomputes strike rate across the group rather than averaging fixtures', () => {
    const result = deriveParticipantAggregates(source([seasonRow]), {});
    const [statistic] = result.statistics;

    // 116 / 56 * 100, not the mean of the per-fixture rates that produced it.
    expect(statistic?.batting).toEqual({
      runsScored: 116,
      ballsFaced: 56,
      fours: 12,
      sixes: 8,
      strikeRate: 207.14,
    });
  });

  test('derives overs and economy from counted legal balls and the fixture divisor', () => {
    const result = deriveParticipantAggregates(
      source([
        row({
          sourceEventCount: 26,
          bowlingDeliveryCount: 26,
          runsConceded: 44,
          wides: 3,
          noBalls: 2,
          legalBallsBowled: 23,
          wicketsTaken: 2,
          ballsPerOver: 6,
        }),
      ]),
      {},
    );

    // Twenty-three legal balls is three overs and five balls, whatever the
    // number of deliveries bowled to produce them.
    expect(result.statistics[0]?.bowling).toEqual({
      runsConceded: 44,
      wides: 3,
      noBalls: 2,
      legalBallsBowled: 23,
      wicketsTaken: 2,
      ballsPerOver: 6,
      oversBowled: '3.5',
      economyRate: 11.48,
    });
  });

  test('reports no rate where the group has no single balls-per-over divisor', () => {
    const result = deriveParticipantAggregates(
      source([
        row({
          competitionGrouped: false,
          seasonGrouped: false,
          competitionId: null,
          competitionName: null,
          season: null,
          sourceEventCount: 30,
          bowlingDeliveryCount: 30,
          runsConceded: 40,
          legalBallsBowled: 28,
          ballsPerOver: null,
        }),
      ]),
      {},
    );

    expect(result.status).toBe('partial');
    expect(result.warnings.map((warning) => warning.code)).toEqual(['MIXED_BALLS_PER_OVER']);
    expect(result.statistics[0]?.bowling).toMatchObject({
      legalBallsBowled: 28,
      ballsPerOver: null,
      oversBowled: null,
      economyRate: null,
    });
  });

  test('distinguishes a participant who did not bat from one who scored nothing', () => {
    const bowledOnly = deriveParticipantAggregates(
      source([row({ sourceEventCount: 6, bowlingDeliveryCount: 6, legalBallsBowled: 6 })]),
      {},
    );
    const scoredNothing = deriveParticipantAggregates(
      source([row({ sourceEventCount: 3, battingDeliveryCount: 3, ballsFaced: 3 })]),
      {},
    );

    expect(bowledOnly.statistics[0]?.batting).toBeNull();
    expect(scoredNothing.statistics[0]?.batting).toMatchObject({
      runsScored: 0,
      ballsFaced: 3,
      strikeRate: 0,
    });
    expect(scoredNothing.statistics[0]?.bowling).toBeNull();
  });

  test('leaves a rate undefined rather than reporting zero when nothing was faced', () => {
    const result = deriveParticipantAggregates(
      source([row({ sourceEventCount: 2, battingDeliveryCount: 2, ballsFaced: 0 })]),
      {},
    );

    expect(result.statistics[0]?.batting?.strikeRate).toBeNull();
  });

  test('carries the season identifier only where the competition is known', () => {
    const result = deriveParticipantAggregates(
      source([
        seasonRow,
        row({
          seasonGrouped: true,
          competitionId: null,
          competitionName: null,
          season: '2018',
          sourceEventCount: 4,
          battingDeliveryCount: 4,
        }),
      ]),
      { createSeasonId: (identity) => `season_${identity.competitionId}_${identity.label}` },
    );

    const [known, unknown] = result.statistics;
    expect(known).toMatchObject({
      scope: 'season',
      competitionId: '10',
      competitionName: 'Test League',
      seasonId: 'season_10_2016/17',
      season: '2016/17',
    });
    expect(unknown).toMatchObject({
      scope: 'season',
      competitionId: null,
      seasonId: null,
      season: '2018',
    });
    expect(result.warnings).toEqual([
      {
        code: 'COMPETITION_UNKNOWN',
        message: 'These fixtures are published without a competition.',
        season: '2018',
      },
    ]);
  });

  test('filters to one level when a scope is requested', () => {
    const result = deriveParticipantAggregates(source([seasonRow, competitionRow, careerRow]), {
      scope: 'career',
    });

    expect(result.statistics).toHaveLength(1);
    expect(result.statistics[0]?.scope).toBe('career');
  });

  test('warns rather than publishing an all-zero career for a participant with no events', () => {
    // The empty grouping set still yields one row when nothing matched.
    const result = deriveParticipantAggregates(
      source([
        row({
          competitionGrouped: false,
          seasonGrouped: false,
          competitionId: null,
          competitionName: null,
          season: null,
          fixtureCount: 0,
          sourceEventCount: 0,
        }),
      ]),
      {},
    );

    expect(result.statistics).toEqual([]);
    expect(result.status).toBe('partial');
    expect(result.warnings.map((warning) => warning.code)).toEqual(['NO_ACCEPTED_EVENTS']);
  });

  test('gives each level a distinct, stable statistic identifier', () => {
    const first = deriveParticipantAggregates(source([seasonRow, competitionRow, careerRow]), {});
    const second = deriveParticipantAggregates(source([seasonRow, competitionRow, careerRow]), {});

    const identifiers = first.statistics.map((statistic) => statistic.statisticId);
    expect(new Set(identifiers).size).toBe(3);
    expect(identifiers.every((identifier) => identifier.startsWith('stat_'))).toBe(true);
    expect(second.statistics.map((statistic) => statistic.statisticId)).toEqual(identifiers);
  });

  test('separates participants sharing a display name by identifier', () => {
    const rows = [careerRow];
    const first = deriveParticipantAggregates({ ...source(rows), participantId: '101' }, {});
    const second = deriveParticipantAggregates({ ...source(rows), participantId: '202' }, {});

    expect(first.statistics[0]?.participantName).toBe(second.statistics[0]?.participantName);
    expect(first.statistics[0]?.statisticId).not.toBe(second.statistics[0]?.statisticId);
  });
});

